  trapTitle: { en: (a, b) => `Why close to 90% between ${a} and ${b}?`, nl: (a, b) => `Waarom bijna 90% tussen ${a} en ${b}?`, fr: (a, b) => `Pourquoi près de 90% entre ${a} et ${b} ?` },
  trapBody: {
    en: b => `Three low-wage discounts shrink as your pay rises: your employer's structural reduction (up to 30 cents per extra €), your social work bonus (27–32 cents per extra €) and the tax credit tied to that bonus. So each extra euro pays the normal taxes <em>and</em> costs you part of those discounts. Above ${b} they're used up and the rate falls back to about 70%.`,
    nl: b => `Drie kortingen voor lage lonen krimpen naarmate je loon stijgt: de structurele vermindering van je werkgever (tot 30 cent per extra €), je sociale werkbonus (27–32 cent per extra €) en de fiscale werkbonus die eraan gekoppeld is. Elke extra euro betaalt dus de gewone belastingen <em>én</em> kost je een deel van die kortingen. Boven ${b} zijn ze opgebruikt en zakt het tarief terug naar ongeveer 70%.`,
    fr: b => `Trois réductions pour bas salaires diminuent quand votre salaire augmente : la réduction structurelle de votre employeur (jusqu'à 30 centimes par € supplémentaire), votre bonus à l'emploi social (27 à 32 centimes par € supplémentaire) et le bonus fiscal qui y est lié. Chaque euro supplémentaire paie donc les impôts normaux <em>et</em> vous fait perdre une partie de ces réductions. Au-delà de ${b}, elles sont épuisées et le taux retombe à environ 70%.`,
  },
  topTitle: {
    en: (top, cap) => `Why the step at ${top}${cap ? ` and the small dip at ${cap}` : ''}?`,
    nl: (top, cap) => `Waarom de sprong bij ${top}${cap ? ` en de kleine dip bij ${cap}` : ''}?`,
    fr: (top, cap) => `Pourquoi la marche à ${top}${cap ? ` et le petit creux à ${cap}` : ''} ?`,
  },
  topBody: {
    en: (top, br, cap, capAmt) => `From ${top} your net taxable income passes ${br}, so the top 50% income tax bracket starts, and the communal tax on it grows too.${cap ? ` At ${cap} the special social security contribution reaches its yearly cap (${capAmt}), so it stops growing and the rate drops slightly.` : ''}`,
    nl: (top, br, cap, capAmt) => `Vanaf ${top} komt je netto belastbaar inkomen boven ${br}: de hoogste schijf van 50% begint, en de gemeentebelasting daarop stijgt mee.${cap ? ` Bij ${cap} bereikt de bijzondere bijdrage sociale zekerheid haar jaarplafond (${capAmt}), dus stijgt ze niet meer en daalt het tarief licht.` : ''}`,
    fr: (top, br, cap, capAmt) => `À partir de ${top}, votre revenu net imposable dépasse ${br} : la tranche supérieure de 50% commence, et la taxe communale qui s'y ajoute augmente aussi.${cap ? ` À ${cap}, la cotisation spéciale de sécurité sociale atteint son plafond annuel (${capAmt}) : elle cesse d'augmenter et le taux baisse légèrement.` : ''}`,
  },

