  // Tooltips
  'tip.monthsPaid': { en: n => `${n} months paid`, nl: n => `${n} betaalde maanden`, fr: n => `${n} mois payés` },
  'tip.f12': {
    en: `Just 12 monthly salaries, with no 13th month and no double holiday pay. Rare for white-collar jobs.`,
    nl: `Gewoon 12 maandlonen, zonder dertiende maand of dubbel vakantiegeld. Zeldzaam voor bedienden.`,
    fr: `Seulement 12 salaires mensuels, sans treizième mois ni double pécule de vacances. Rare pour les employés.`,
  },
  'tip.f1385': {
    en: `12 months + a 13th month + double holiday pay of 85% of one monthly salary.`,
    nl: `12 maanden + een dertiende maand + dubbel vakantiegeld van 85% van één maandloon.`,
    fr: `12 mois + un treizième mois + un double pécule de vacances de 85% d'un salaire mensuel.`,
  },
  'tip.f1385m': {
    en: `85% is the part of double holiday pay that employee social security (13.07%) is charged on.`,
    nl: `85% is het deel van het dubbel vakantiegeld waarop de werknemersbijdrage (13,07%) wordt geheven.`,
    fr: `85% est la part du double pécule de vacances soumise aux cotisations personnelles (13,07%).`,
  },
  'tip.f1392': {
    en: `The usual white-collar package: 12 months + a 13th month (end-of-year bonus) + double holiday pay of 92% of one monthly salary.`,
    nl: `Het gebruikelijke pakket voor bedienden: 12 maanden + een dertiende maand (eindejaarspremie) + dubbel vakantiegeld van 92% van één maandloon.`,
    fr: `Le package habituel des employés : 12 mois + un treizième mois (prime de fin d'année) + un double pécule de vacances de 92% d'un salaire mensuel.`,
  },
  'tip.f1392m': {
    en: `Employee social security is charged on 85% of it, the other 7% is exempt, and your employer pays no contributions on double holiday pay.`,
    nl: `De werknemersbijdrage wordt op 85% ervan geheven, de overige 7% is vrijgesteld, en je werkgever betaalt geen bijdragen op dubbel vakantiegeld.`,
    fr: `Les cotisations personnelles portent sur 85%, les 7% restants sont exonérés, et votre employeur ne paie pas de cotisations sur le double pécule.`,
  },
  'tip.jointH': { en: `Joint tax return`, nl: `Gezamenlijke aangifte`, fr: `Déclaration commune` },
  'tip.joint': {
    en: mq => `Married and legally cohabiting partners file one return. Each partner is taxed in their own column, but the marital quotient can move up to ${mq} to a partner who earns less than 30% of the couple's combined income. A tax-free allowance one partner can't use moves to the other.`,
    nl: mq => `Gehuwden en wettelijk samenwonenden dienen één aangifte in. Elke partner wordt in een eigen kolom belast, maar het huwelijksquotiënt kan tot ${mq} overdragen naar een partner die minder dan 30% van het gezamenlijke inkomen verdient. Een belastingvrije som die de ene partner niet kan gebruiken, gaat naar de andere.`,
    fr: mq => `Les conjoints et cohabitants légaux remplissent une seule déclaration. Chacun est imposé dans sa propre colonne, mais le quotient conjugal peut attribuer jusqu'à ${mq} au partenaire qui gagne moins de 30% des revenus du couple. Une quotité exemptée qu'un partenaire ne peut pas utiliser passe à l'autre.`,
  },
